candidates.raw:
    /* 1. Input Validation */
    if (gb_input.enable != TRUE32 || gb_input.rate_rad_s == NULL) {
        gb_state.mode = GB_FAULT;
        goto publish_fault;
    }
    if (!isfinite(gb_config.stationary_limit_rad_s) || gb_config.stationary_limit_rad_s < 0.0 ||
        !isfinite(gb_config.max_sample_delta_rad_s) || gb_config.max_sample_delta_rad_s < 0.0 ||
        !isfinite(gb_config.max_stddev_rad_s) || gb_config.max_stddev_rad_s < 0.0 ||
        gb_config.required_samples < 3 || gb_config.required_samples > 100 ||
        gb_config.max_rejected_windows < 1 || gb_config.max_rejected_windows > 20 ||
        !isfinite(gb_config.drift_limit_rad_s) || gb_config.drift_limit_rad_s < 0.0 ||
        gb_config.drift_confirm_samples < 1 || gb_config.drift_confirm_samples > 20) {
        gb_state.mode = GB_FAULT;
        goto publish_fault;
    }

    /* 2. Disable Handling */
    if (gb_input.enable != TRUE32) {
        gb_state.mode = GB_COLLECT;
        gb_state.count = 0;
        gb_state.rejected_windows = 0;
        gb_state.has_previous = 0;
        gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
        gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
        gb_state.drift_count = 0;

        gb_output.mode = gb_state.mode;
        gb_output.count = 0;
        gb_output.rejected_windows = 0;
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
        gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
        return;
    }

    /* 3. Drift Check in READY Mode */
    if (gb_state.mode == GB_READY) {
        adcs_vec3_t diff = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.bias_rad_s);
        double dist = adcs_vec3_norm(&diff);

        if (dist <= gb_config.drift_limit_rad_s) {
            gb_state.drift_count = 0;
        } else {
            gb_state.drift_count++;
            if (gb_state.drift_count >= gb_config.drift_confirm_samples) {
                gb_state.mode = GB_COLLECT;
                gb_state.count = 0;
                gb_state.has_previous = 0;
                gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
                gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
            }
        }

        gb_output.mode = gb_state.mode;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
        return;
    }

    /* 4. Sample Rejection Logic */
    gb_output.rejection = GB_REJECT_NONE;
    int rejected = 0;

    double rate_norm = adcs_vec3_norm(gb_input.rate_rad_s);
    if (rate_norm > gb_config.stationary_limit_rad_s) {
        gb_output.rejection = GB_REJECT_RATE;
        rejected = 1;
    } else if (gb_state.has_previous) {
        adcs_vec3_t delta = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.previous_rate_rad_s);
        double delta_norm = adcs_vec3_norm(&delta);
        if (delta_norm > gb_config.max_sample_delta_rad_s) {
            gb_output.rejection = GB_REJECT_STEP;
            rejected = 1;
        }
    }

    if (rejected) {
        gb_state.rejected_windows++;
        if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
            gb_state.mode = GB_FAULT;
        }

        gb_state.count = 0;
        gb_state.has_previous = 0;
        gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
        gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;

        gb_output.mode = gb_state.mode;
        gb_output.count = 0;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
        gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
        return;
    }

    /* 5. Welford Update (Per-Axis) */
    if (gb_state.count == 0) {
        gb_state.mean_rad_s = *gb_input.rate_rad_s;
        gb_state.m2_rad_s2.x = 0.0;
        gb_state.m2_rad_s2.y = 0.0;
        gb_state.m2_rad_s2.z = 0.0;
    } else {
        double n = (double)gb_state.count;
        double n_prev = n - 1.0;

        // X Axis
        double prev_mean_x = gb_state.mean_rad_s.x;
        double diff_x = gb_input.rate_rad_s->x - prev_mean_x;
        gb_state.mean_rad_s.x = prev_mean_x + diff_x / n;
        double new_diff_x = gb_input.rate_rad_s->x - gb_state.mean_rad_s.x;
        gb_state.m2_rad_s2.x += diff_x * new_diff_x;

        // Y Axis
        double prev_mean_y = gb_state.mean_rad_s.y;
        double diff_y = gb_input.rate_rad_s->y - prev_mean_y;
        gb_state.mean_rad_s.y = prev_mean_y + diff_y / n;
        double new_diff_y = gb_input.rate_rad_s->y - gb_state.mean_rad_s.y;
        gb_state.m2_rad_s2.y += diff_y * new_diff_y;

        // Z Axis
        double prev_mean_z = gb_state.mean_rad_s.z;
        double diff_z = gb_input.rate_rad_s->z - prev_mean_z;
        gb_state.mean_rad_s.z = prev_mean_z + diff_z / n;
        double new_diff_z = gb_input.rate_rad_s->z - gb_state.mean_rad_s.z;
        gb_state.m2_rad_s2.z += diff_z * new_diff_z;
    }

    gb_state.has_previous = 1;
    gb_state.previous_rate_rad_s = *gb_input.rate_rad_s;
    gb_state.count++;

    /* 6. Variance Check and Bias Locking */
    if (gb_state.count == gb_config.required_samples) {
        double var_x = gb_state.m2_rad_s2.x / gb_state.count;
        double var_y = gb_state.m2_rad_s2.y / gb_state.count;
        double var_z = gb_state.m2_rad_s2.z / gb_state.count;
        double max_var_sq = gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s;

        if (var_x > max_var_sq || var_y > max_var_sq || var_z > max_var_sq) {
            gb_output.rejection = GB_REJECT_VARIANCE;

            gb_state.rejected_windows++;
            if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
                gb_state.mode = GB_FAULT;
            }

            gb_state.count = 0;
            gb_state.has_previous = 0;
            gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
            gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;

            gb_output.mode = gb_state.mode;
            gb_output.count = 0;
            gb_output.rejected_windows = gb_state.rejected_windows;
            gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
            gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
            return;
        }

        // Success: Lock Bias and Variance
        gb_state.bias_rad_s = gb_state.mean_rad_s;
        gb_state.variance_rad_s2.x = var_x;
        gb_state.variance_rad_s2.y = var_y;
        gb_state.variance_rad_s2.z = var_z;
        gb_state.mode = GB_READY;
    }

publish_fault:
    /* 7. Publish Output */
    gb_output.mode = gb_state.mode;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;

    if (gb_state.mode == GB_READY) {
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
    } else {
        gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
        if (gb_state.mode == GB_COLLECT && gb_state.count > 0) {
            gb_output.variance_rad_s2.x = gb_state.m2_rad_s2.x / gb_state.count;
            gb_output.variance_rad_s2.y = gb_state.m2_rad_s2.y / gb_state.count;
            gb_output.variance_rad_s2.z = gb_state.m2_rad_s2.z / gb_state.count;
        } else {
            gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
        }
    }

