if ((&gb_input == NULL) || (&gb_config == NULL) || (&gb_state == NULL) || (&gb_output == NULL)) {
    return;
}

// Check enable
if (!gb_input.enable) {
    gb_state.mode = GB_OFF;
    gb_state.count = 0;
    gb_state.rejected_windows = 0;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
    gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
    gb_state.bias_rad_s.x = 0.0; gb_state.bias_rad_s.y = 0.0; gb_state.bias_rad_s.z = 0.0;
    gb_state.variance_rad_s2.x = 0.0; gb_state.variance_rad_s2.y = 0.0; gb_state.variance_rad_s2.z = 0.0;
    gb_state.drift_count = 0;
    gb_output.mode = GB_OFF;
    gb_output.count = 0;
    gb_output.rejected_windows = 0;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
    return;
}

// Check Config Validity
int config_valid = 1;
if (!isfinite(gb_config.stationary_limit_rad_s) || (gb_config.stationary_limit_rad_s < 0.0)) config_valid = 0;
if (!isfinite(gb_config.max_sample_delta_rad_s) || (gb_config.max_sample_delta_rad_s < 0.0)) config_valid = 0;
if (!isfinite(gb_config.max_stddev_rad_s) || (gb_config.max_stddev_rad_s < 0.0)) config_valid = 0;
if ((gb_config.required_samples < 3) || (gb_config.required_samples > 100)) config_valid = 0;
if ((gb_config.max_rejected_windows < 1) || (gb_config.max_rejected_windows > 20)) config_valid = 0;
if (!isfinite(gb_config.drift_limit_rad_s) || (gb_config.drift_limit_rad_s < 0.0)) config_valid = 0;
if ((gb_config.drift_confirm_samples < 1) || (gb_config.drift_confirm_samples > 20)) config_valid = 0;

if (!config_valid) {
    gb_state.mode = GB_FAULT;
    gb_output.mode = GB_FAULT;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = gb_state.bias_rad_s;
    gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
    return;
}

// 2. Handle FAULT State
if (gb_state.mode == GB_FAULT) {
    gb_output.mode = GB_FAULT;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = gb_state.bias_rad_s;
    gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
    return;
}

// 3. Handle READY Mode Drift Detection
if (gb_state.mode == GB_READY) {
    double dist = adcs_vec3_norm(gb_input.rate_rad_s);
    if (dist <= gb_config.drift_limit_rad_s) {
        gb_state.drift_count = 0;
        // Still READY, output frozen state
        gb_output.mode = GB_READY;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
        return;
    } else {
        gb_state.drift_count++;
        if (gb_state.drift_count >= gb_config.drift_confirm_samples) {
            // Discard calibration, restart from empty window
            gb_state.mode = GB_COLLECT;
            gb_state.count = 0;
            gb_state.has_previous = 0;
            gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
            gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
            gb_state.drift_count = 0;
            // Fall through to COLLECT logic to process current sample
        } else {
            // Not confirmed yet, stay READY
            gb_output.mode = GB_READY;
            gb_output.count = gb_state.count;
            gb_output.rejected_windows = gb_state.rejected_windows;
            gb_output.rejection = GB_REJECT_NONE;
            gb_output.bias_rad_s = gb_state.bias_rad_s;
            gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
            return;
        }
    }
}

// 4. Process Sample in COLLECT Mode
// At this point, mode must be GB_COLLECT

gb_rejection_t reject_reason = GB_REJECT_NONE;
int sample_accepted = 1;

// Check Norm
double norm = adcs_vec3_norm(gb_input.rate_rad_s);
if (norm > gb_config.stationary_limit_rad_s) {
    sample_accepted = 0;
    reject_reason = GB_REJECT_RATE;
}

// Check Delta
if (sample_accepted && gb_state.has_previous) {
    adcs_vec3_t delta = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.previous_rate_rad_s);
    double delta_norm = adcs_vec3_norm(&delta);
    if (delta_norm > gb_config.max_sample_delta_rad_s) {
        sample_accepted = 0;
        reject_reason = GB_REJECT_STEP;
    }
}

if (!sample_accepted) {
    // Clear window
    gb_state.count = 0;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
    gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;

    gb_state.rejected_windows++;

    gb_output.mode = GB_COLLECT;
    gb_output.count = 0;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = reject_reason;
    gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;

    if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
        gb_state.mode = GB_FAULT;
        gb_output.mode = GB_FAULT;
    }
    return;
}

// Sample Accepted
gb_output.rejection = GB_REJECT_NONE;

// Welford Update
if (gb_state.count == 0) {
    gb_state.mean_rad_s = *gb_input.rate_rad_s;
    gb_state.m2_rad_s2.x = 0.0;
    gb_state.m2_rad_s2.y = 0.0;
    gb_state.m2_rad_s2.z = 0.0;
} else {
    adcs_vec3_t diff = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.mean_rad_s);
    gb_state.mean_rad_s = adcs_vec3_add(&gb_state.mean_rad_s, &adcs_vec3_scale(&diff, 1.0 / (gb_state.count + 1)));
    adcs_vec3_t diff_new = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.mean_rad_s);
    gb_state.m2_rad_s2.x += diff.x * diff_new.x;
    gb_state.m2_rad_s2.y += diff.y * diff_new.y;
    gb_state.m2_rad_s2.z += diff.z * diff_new.z;
}

gb_state.count++;
gb_state.has_previous = 1;
gb_state.previous_rate_rad_s = *gb_input.rate_rad_s;

// Check Variance if required_samples reached
if (gb_state.count == gb_config.required_samples) {
    int variance_ok = 1;
    double var_x = gb_state.m2_rad_s2.x / gb_state.count;
    double var_y = gb_state.m2_rad_s2.y / gb_state.count;
    double var_z = gb_state.m2_rad_s2.z / gb_state.count;

    if ((var_x > gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s) ||
        (var_y > gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s) ||
        (var_z > gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s)) {
        variance_ok = 0;
    }

    if (variance_ok) {
        gb_state.mode = GB_READY;
        gb_state.bias_rad_s = gb_state.mean_rad_s;
        gb_state.variance_rad_s2.x = var_x;
        gb_state.variance_rad_s2.y = var_y;
        gb_state.variance_rad_s2.z = var_z;

        gb_output.mode = GB_READY;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
    } else {
        // Noisy window rejected
        gb_state.count = 0;
        gb_state.has_previous = 0;
        gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
        gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;

        gb_state.rejected_windows++;

        gb_output.mode = GB_COLLECT;
        gb_output.count = 0;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_VARIANCE;
        gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
        gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;

        if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
            gb_state.mode = GB_FAULT;
            gb_output.mode = GB_FAULT;
        }
    }
} else {
    // Not enough samples yet
    gb_output.mode = GB_COLLECT;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = gb_state.m2_rad_s2.x / gb_state.count;
    gb_output.variance_rad_s2.y = gb_state.m2_rad_s2.y / gb_state.count;
    gb_output.variance_rad_s2.z = gb_state.m2_rad_s2.z / gb_state.count;
}

